package reliquary.item;

import net.minecraft.core.HolderLookup;
import net.minecraft.core.registries.Registries;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.enchantment.Enchantment;
import net.minecraft.world.item.enchantment.EnchantmentHelper;
import net.minecraft.world.item.enchantment.Enchantments;
import net.minecraft.world.level.Level;
import net.neoforged.neoforge.common.ItemAbilities;
import net.neoforged.neoforge.common.ItemAbility;
import reliquary.entity.LyssaHook;
import reliquary.init.ModDataComponents;

public class RodOfLyssaItem extends ItemBase {
	public RodOfLyssaItem() {
		super(new Properties().stacksTo(1));
	}

	public static int getHookEntityId(ItemStack stack) {
		return stack.getOrDefault(ModDataComponents.HOOK_ENTITY_ID, 0);
	}

	@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
		ItemStack stack = player.getItemInHand(hand);
		int entityId = getHookEntityId(stack);
		if (entityId != 0 && level.getEntity(entityId) instanceof LyssaHook hook) {
			player.swing(hand);
			hook.handleHookRetraction(stack);
			setHookEntityId(stack, 0);
		} else {
			level.playSound(null, player.blockPosition(), SoundEvents.ARROW_SHOOT, SoundSource.NEUTRAL, 0.5F, 0.4F / (level.random.nextFloat() * 0.4F + 0.8F));

			if (!level.isClientSide) {

				HolderLookup.RegistryLookup<Enchantment> registrylookup = level.registryAccess().lookupOrThrow(Registries.ENCHANTMENT);
				int lureLevel = EnchantmentHelper.getEnchantmentLevel(registrylookup.getOrThrow(Enchantments.LURE), player);
				int luckOfTheSeaLevel = EnchantmentHelper.getEnchantmentLevel(registrylookup.getOrThrow(Enchantments.LUCK_OF_THE_SEA), player);

				LyssaHook hook = new LyssaHook(level, player, lureLevel, luckOfTheSeaLevel);
				level.addFreshEntity(hook);

				setHookEntityId(stack, hook.getId());
			}

			player.swing(hand);
		}

		return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
	}

	private void setHookEntityId(ItemStack stack, int entityId) {
		stack.set(ModDataComponents.HOOK_ENTITY_ID, entityId);
	}

	@Override
	public boolean canPerformAction(ItemStack stack, ItemAbility itemAbility) {
		return ItemAbilities.DEFAULT_FISHING_ROD_ACTIONS.contains(itemAbility);
	}
}

package reliquary.entity;

import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.tags.FluidTags;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.FishingHook;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.phys.Vec3;
import reliquary.init.ModEntities;
import reliquary.init.ModItems;
import reliquary.reference.Config;

import java.util.List;
import java.util.Optional;

public class LyssaHook extends FishingHook {
	public LyssaHook(EntityType<LyssaHook> entityType, Level level) {
		this(entityType, level, 0, 0);
	}

	private LyssaHook(EntityType<LyssaHook> entityType, Level level, int luck, int lureSpeed) {
		super(entityType, level, luck, lureSpeed);
	}

	public LyssaHook(Level level, Player fishingPlayer, int lureSpeed, int luck) {
		this(ModEntities.LYSSA_HOOK.get(), level, luck, lureSpeed);
		setOwner(fishingPlayer);
		shoot(fishingPlayer);

		// Reliquary
		speedUp();
	}

	private void shoot(Player fishingPlayer) {
		float f = fishingPlayer.getXRot();
		float f1 = fishingPlayer.getYRot();
		float f2 = Mth.cos(-f1 * ((float) Math.PI / 180F) - (float) Math.PI);
		float f3 = Mth.sin(-f1 * ((float) Math.PI / 180F) - (float) Math.PI);
		float f4 = -Mth.cos(-f * ((float) Math.PI / 180F));
		float f5 = Mth.sin(-f * ((float) Math.PI / 180F));
		double d0 = fishingPlayer.getX() - f3 * 0.3D;
		double d1 = fishingPlayer.getEyeY();
		double d2 = fishingPlayer.getZ() - f2 * 0.3D;
		moveTo(d0, d1, d2, f1, f);
		Vec3 vec3 = new Vec3(-f3, Mth.clamp(-(f5 / f4), -5.0F, 5.0F), -f2);
		double d3 = vec3.length();
		vec3 = vec3.multiply(0.6D / d3 + 0.5D + random.nextGaussian() * 0.0045D, 0.6D / d3 + 0.5D + random.nextGaussian() * 0.0045D,
				0.6D / d3 + 0.5D + random.nextGaussian() * 0.0045D);
		setDeltaMovement(vec3);
		setYRot((float) (Mth.atan2(vec3.x, vec3.z) * (180F / (float) Math.PI)));
		setXRot((float) (Mth.atan2(vec3.y, vec3.horizontalDistance()) * (180F / (float) Math.PI)));
		yRotO = getYRot();
		xRotO = getXRot();
	}

	@Override
	public boolean shouldRenderAtSqrDistance(double distance) {
		// much higher visible range than regular hook
		return distance < 16384;
	}

	public Optional<Player> getFishingPlayer() {
		Entity entity = getOwner();
		return Optional.ofNullable(entity instanceof Player player ? player : null);
	}

	private void speedUp() {
		// faster speed of the hook except for casting down

		if (getDeltaMovement().y() >= 0) {
			setDeltaMovement(getDeltaMovement().multiply(2, 2, 2));
		}
	}

	@Override
	public void tick() {
		super.tick();

		pullItemEntitiesTowardsHook();
	}

	@Override
	protected boolean shouldStopFishing(Player fishingPlayer) {
		ItemStack itemstack = fishingPlayer.getMainHandItem();
		ItemStack itemstack1 = fishingPlayer.getOffhandItem();
		boolean flag = itemstack.getItem() == ModItems.ROD_OF_LYSSA.get();
		boolean flag1 = itemstack1.getItem() == ModItems.ROD_OF_LYSSA.get();
		if (fishingPlayer.isAlive() && (flag || flag1) && distanceToSqr(fishingPlayer) <= 10240.0D) {
			return false;
		} else {
			discard();
			return true;
		}
	}

	private void pullItemEntitiesTowardsHook() {
		if (isAlive() && getHookedIn() == null) {
			float f = 0.0F;
			BlockPos blockpos = blockPosition();

			FluidState fluidState = level().getFluidState(blockpos);
			if (fluidState.is(FluidTags.WATER)) {
				f = fluidState.getHeight(level(), blockpos);
			}

			if (f <= 0F) {
				List<ItemEntity> list = level().getEntitiesOfClass(ItemEntity.class, getBoundingBox().expandTowards(getDeltaMovement()).inflate(3.0D));

				for (ItemEntity e : list) {
					Vec3 pullVector = new Vec3(getX() - e.getX(), getY() - e.getY(), getZ() - e.getZ()).normalize();
					e.setDeltaMovement(pullVector.multiply(0.4D, 0.4D, 0.4D));
				}
			}
		}
	}

	public void handleHookRetraction(ItemStack stack) {
		if (!level().isClientSide) {
			Entity hookedIn = getHookedIn();
			if (hookedIn != null && getFishingPlayer().map(Entity::isCrouching).orElse(false) && canStealFromEntity()) {
				stealFromLivingEntity();
				discard();
			} else {
				if (!level().isClientSide && getFishingPlayer().isPresent() && hookedIn != null) {
					bringInHookedEntity();
					level().broadcastEntityEvent(this, (byte) 31);
					discard();
				} else {
					super.retrieve(stack);
				}
			}

			pullItemEntitiesWithHook();
		}

	}

	private void bringInHookedEntity() {
		Entity hookedIn = getHookedIn();
		if (hookedIn != null) {
			super.pullEntity(hookedIn);
		}

		if (hookedIn instanceof ItemEntity) {
			hookedIn.setDeltaMovement(hookedIn.getDeltaMovement().multiply(4D, 4D, 4D));
		} else if (hookedIn instanceof LivingEntity) {
			hookedIn.setDeltaMovement(hookedIn.getDeltaMovement().multiply(1, 1.5D, 1));
		}
	}

	private boolean canStealFromEntity() {
		Entity hookedIn = getHookedIn();
		return hookedIn instanceof LivingEntity && (Config.COMMON.items.rodOfLyssa.stealFromPlayers.get() || !(hookedIn instanceof Player))
				&& Config.COMMON.items.rodOfLyssa.canStealFromEntity(hookedIn);
	}

	private void pullItemEntitiesWithHook() {
		List<ItemEntity> pullingItemsList = level().getEntitiesOfClass(ItemEntity.class,
				getBoundingBox().expandTowards(getDeltaMovement()).inflate(1.0D, 1.0D, 1.0D));

		getFishingPlayer().ifPresent(p -> {
			for (ItemEntity e : pullingItemsList) {
				double d1 = p.getX() - getX();
				double d3 = p.getY() - getY();
				double d5 = p.getZ() - getZ();
				double d7 = Math.sqrt(d1 * d1 + d3 * d3 + d5 * d5);
				double d9 = 0.1D;
				e.setDeltaMovement(d1 * d9, d3 * d9 + Math.sqrt(d7) * 0.08D, d5 * d9);
			}
		});
	}

	private void stealFromLivingEntity() {
		if (!(getHookedIn() instanceof LivingEntity livingEntity)) {
			return;
		}
		EquipmentSlot slotBeingStolenFrom = EquipmentSlot.values()[level().random.nextInt(EquipmentSlot.values().length)];

		ItemStack stolenStack = livingEntity.getItemBySlot(slotBeingStolenFrom);
		if (stolenStack.isEmpty() && Boolean.TRUE.equals(Config.COMMON.items.rodOfLyssa.stealFromVacantSlots.get())) {
			for (EquipmentSlot slot : EquipmentSlot.values()) {
				stolenStack = livingEntity.getItemBySlot(slot);
				if (!stolenStack.isEmpty() && canDropFromSlot(livingEntity, slot)) {
					slotBeingStolenFrom = slot;
					break;
				}
			}
		}

		float failProbabilityFactor;

		Optional<Player> p = getFishingPlayer();

		if (p.isEmpty()) {
			return;
		}

		Player fishingPlayer = p.get();

		if (Boolean.TRUE.equals(Config.COMMON.items.rodOfLyssa.useLeveledFailureRate.get())) {
			failProbabilityFactor = 1F
					/ ((float) Math.sqrt(Math.max(1, Math.min(fishingPlayer.experienceLevel, Config.COMMON.items.rodOfLyssa.levelCapForLeveledFormula.get())))
							* 2);
		} else {
			failProbabilityFactor = Config.COMMON.items.rodOfLyssa.flatStealFailurePercentRate.get() / 100F;
		}

		if ((random.nextFloat() <= failProbabilityFactor || (stolenStack.isEmpty() && Config.COMMON.items.rodOfLyssa.failStealFromVacantSlots.get()))
				&& Boolean.TRUE.equals(Config.COMMON.items.rodOfLyssa.angerOnStealFailure.get())) {
			livingEntity.hurt(damageSources().playerAttack(fishingPlayer), 0.0F);
			return;
		}
		if (!stolenStack.isEmpty() && level() instanceof ServerLevel serverLevel) {
			int randomItemDamage = level().random.nextInt(3);
			stolenStack.hurtAndBreak(randomItemDamage, serverLevel, livingEntity, e -> {
			});
			if (!stolenStack.isEmpty()) {
				ItemEntity entityitem = new ItemEntity(level(), getX(), getY(), getZ(), stolenStack);
				entityitem.setPickUpDelay(5);
				double d1 = fishingPlayer.getX() - getX();
				double d3 = fishingPlayer.getY() - getY();
				double d5 = fishingPlayer.getZ() - getZ();
				double d7 = Math.sqrt(d1 * d1 + d3 * d3 + d5 * d5);
				double d9 = 0.1D;
				entityitem.setDeltaMovement(d1 * d9, d3 * d9 + Math.sqrt(d7) * 0.08D, d5 * d9);
				level().addFreshEntity(entityitem);
			}

			livingEntity.setItemSlot(slotBeingStolenFrom, ItemStack.EMPTY);
		}
	}

	private boolean canDropFromSlot(LivingEntity entity, EquipmentSlot slot) {
		if (!(entity instanceof Mob mob)) {
			return true;
		}

		if (slot.getType() == EquipmentSlot.Type.HAND) {
			return mob.handDropChances[slot.getIndex()] > -1;
		} else {
			return mob.armorDropChances[slot.getIndex()] > -1;
		}
	}
}

public static class RodOfLyssaSettings {
	public final BooleanValue useLeveledFailureRate;
	public final IntValue levelCapForLeveledFormula;
	public final IntValue flatStealFailurePercentRate;
	public final BooleanValue stealFromVacantSlots;
	public final BooleanValue failStealFromVacantSlots;
	public final BooleanValue angerOnStealFailure;
	public final BooleanValue stealFromPlayers;
	private static final String ENTITY_NAME_MATCHER = "[a-z1-9_.-]+:[a-z1-9_/.-]+";
	@SuppressWarnings("java:S4968")
	// ? extends String is the type parameter returned from defineList so it can't be just String here
	public final ModConfigSpec.ConfigValue<List<? extends String>> entityBlockList;
	@Nullable
	private Set<EntityType<?>> blockedEntities = null;

	RodOfLyssaSettings(ModConfigSpec.Builder builder) {
		builder.comment("Rod of Lyssa settings").translation(translationKey("items.rodOfLyssa")).push("rodOfLyssa");

		useLeveledFailureRate = builder.comment("Whether level influences stealing failure rate of the rod").define("useLeveledFailureRate", true);

		levelCapForLeveledFormula = builder.comment("The experience level cap after which the failure rate is at a minimum and doesn't get better")
				.defineInRange("levelCapForLeveledFormula", 100, 1, 900);

		flatStealFailurePercentRate = builder.comment("The flat failure rate in case failure rate isn't influenced by player's level")
				.defineInRange("flatStealFailurePercentRate", 10, 0, 100);

		stealFromVacantSlots = builder.comment(
				"If set to false it goes through additional 4 accessible slots and looks for items in case the one selected randomly was empty")
				.define("stealFromVacantSlots", true);

		failStealFromVacantSlots = builder.comment("Whether stealing from an empty slot triggers failure even if otherwise it would be successful")
				.define("failStealFromVacantSlots", false);

		angerOnStealFailure = builder.comment("Whether entities get angry at player if stealing fails").define("angerOnStealFailure", true);

		stealFromPlayers = builder.comment("Allows switching stealing from player on and off").define("stealFromPlayers", true);

		entityBlockList = builder.comment("List of entities on which lyssa rod doesn't work - full registry name is required here").defineList(
				"entityBlockList", new ArrayList<>(), () -> BuiltInRegistries.ENTITY_TYPE.getKey(EntityType.ZOMBIE).toString(),
				mapping -> ((String) mapping).matches(ENTITY_NAME_MATCHER));
		builder.pop();
	}

	public boolean canStealFromEntity(Entity entity) {
		if (blockedEntities == null) {
			initBlockedEntityTypes();
		}
		return !blockedEntities.contains(entity.getType());
	}

	private void initBlockedEntityTypes() {
		blockedEntities = new HashSet<>();
		for (var entityName : entityBlockList.get()) {
			BuiltInRegistries.ENTITY_TYPE.getOptional(ResourceLocation.parse(entityName)).ifPresent(blockedEntities::add);
		}
	}
}

